-- 097: 成果类型扩展、知识产权生命周期及获奖申报评审。
-- 旧有论文/著作/专利/获奖表继续作为历史成果来源；本迁移只增加扩展台账和可追溯的业务流程。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研成果扩展记录" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "成果类别" varchar(30) NOT NULL,
    "成果名称" varchar(500) NOT NULL,
    "年度" integer,
    "完成日期" date,
    "负责人编号" integer REFERENCES "人员"("编号"),
    "关联成果类型" integer,
    "关联成果编号" integer,
    "关联项目编号" integer,
    "成果摘要" text,
    "扩展字段" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "附件路径" text,
    "审核状态" varchar(12) NOT NULL DEFAULT '待审核',
    "审核意见" varchar(2000),
    "审核人编号" integer REFERENCES "人员"("编号"),
    "审核时间" timestamp without time zone,
    "创建人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_科研成果扩展记录_类别" CHECK ("成果类别" IN ('研究报告','鉴定成果','艺术作品','标准','药品证书','新品种','集成电路布图','其他')),
    CONSTRAINT "ck_科研成果扩展记录_年度" CHECK ("年度" IS NULL OR "年度" BETWEEN 1900 AND 2200),
    CONSTRAINT "ck_科研成果扩展记录_关联类型" CHECK ("关联成果类型" IS NULL OR "关联成果类型" BETWEEN 1 AND 4),
    CONSTRAINT "ck_科研成果扩展记录_审核状态" CHECK ("审核状态" IN ('待审核','已通过','已退回')),
    CONSTRAINT "ck_科研成果扩展记录_名称" CHECK (length(btrim("成果名称")) BETWEEN 1 AND 500)
);
CREATE INDEX IF NOT EXISTS "ix_科研成果扩展记录_类别年度" ON "科研成果扩展记录" ("成果类别","年度" DESC,"编号" DESC);
CREATE INDEX IF NOT EXISTS "ix_科研成果扩展记录_负责人" ON "科研成果扩展记录" ("负责人编号","审核状态","更新时间" DESC);

CREATE TABLE IF NOT EXISTS "知识产权记录" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "知识产权类型" varchar(20) NOT NULL,
    "名称" varchar(500) NOT NULL,
    "状态" varchar(20) NOT NULL DEFAULT '筹备',
    "申请号" varchar(200),
    "申请日期" date,
    "公开编号" varchar(200),
    "公开日期" date,
    "证书号" varchar(200),
    "授权日期" date,
    "法律状态" varchar(50),
    "权利人" varchar(500),
    "负责人编号" integer REFERENCES "人员"("编号"),
    "代理机构" varchar(300),
    "代理联系人" varchar(100),
    "关联项目编号" integer,
    "总费用" numeric(18,2) NOT NULL DEFAULT 0,
    "已缴费用" numeric(18,2) NOT NULL DEFAULT 0,
    "下次缴费日期" date,
    "摘要" text,
    "扩展字段" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "附件路径" text,
    "创建人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_知识产权记录_类型" CHECK ("知识产权类型" IN ('专利','著作权','标准','药品证书','新品种','集成电路布图')),
    CONSTRAINT "ck_知识产权记录_状态" CHECK ("状态" IN ('筹备','申请中','受理','审查中','已授权','已登记','已失效','已撤回')),
    CONSTRAINT "ck_知识产权记录_费用" CHECK ("总费用" >= 0 AND "已缴费用" >= 0 AND "已缴费用" <= "总费用"),
    CONSTRAINT "ck_知识产权记录_名称" CHECK (length(btrim("名称")) BETWEEN 1 AND 500)
);
CREATE INDEX IF NOT EXISTS "ix_知识产权记录_状态缴费" ON "知识产权记录" ("状态","下次缴费日期","编号");
CREATE INDEX IF NOT EXISTS "ix_知识产权记录_负责人" ON "知识产权记录" ("负责人编号","更新时间" DESC);

CREATE TABLE IF NOT EXISTS "知识产权事件" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "知识产权编号" bigint NOT NULL REFERENCES "知识产权记录"("编号") ON DELETE CASCADE,
    "事件类型" varchar(20) NOT NULL,
    "事件日期" date NOT NULL DEFAULT CURRENT_DATE,
    "状态" varchar(20),
    "事件说明" varchar(2000),
    "凭证编号" varchar(200),
    "凭证路径" text,
    "金额" numeric(18,2) NOT NULL DEFAULT 0,
    "下次缴费日期" date,
    "操作人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "操作时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_知识产权事件_类型" CHECK ("事件类型" IN ('申请','受理','审查','授权','登记','变更','缴费','年费提醒','失效','撤回')),
    CONSTRAINT "ck_知识产权事件_金额" CHECK ("金额" >= 0)
);
CREATE INDEX IF NOT EXISTS "ix_知识产权事件_产权时间" ON "知识产权事件" ("知识产权编号","事件日期" DESC,"编号" DESC);

CREATE TABLE IF NOT EXISTS "知识产权缴费提醒" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "知识产权编号" bigint NOT NULL REFERENCES "知识产权记录"("编号") ON DELETE CASCADE,
    "费用类型" varchar(30) NOT NULL,
    "应缴日期" date NOT NULL,
    "应缴金额" numeric(18,2) NOT NULL DEFAULT 0,
    "状态" varchar(12) NOT NULL DEFAULT '待提醒',
    "提醒提前天数" integer NOT NULL DEFAULT 30,
    "提醒时间" timestamp without time zone,
    "处理时间" timestamp without time zone,
    "处理人编号" integer REFERENCES "人员"("编号"),
    "处理说明" varchar(1000),
    "创建人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_知识产权缴费提醒_状态" CHECK ("状态" IN ('待提醒','已提醒','已缴费','已取消')),
    CONSTRAINT "ck_知识产权缴费提醒_金额" CHECK ("应缴金额" >= 0),
    CONSTRAINT "ck_知识产权缴费提醒_提前天数" CHECK ("提醒提前天数" BETWEEN 0 AND 3650)
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_知识产权缴费提醒_产权费用日期" ON "知识产权缴费提醒" ("知识产权编号","费用类型","应缴日期");
CREATE INDEX IF NOT EXISTS "ix_知识产权缴费提醒_待办" ON "知识产权缴费提醒" ("状态","应缴日期");

CREATE TABLE IF NOT EXISTS "获奖申报批次" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "计划年度" integer NOT NULL,
    "批次名称" varchar(200) NOT NULL,
    "获奖类别" varchar(100) NOT NULL,
    "申报开始日期" date NOT NULL,
    "申报截止日期" date NOT NULL,
    "评审开始日期" date,
    "评审截止日期" date,
    "申报限额" integer,
    "申报资格规则" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "评审方案" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "状态" varchar(12) NOT NULL DEFAULT '草稿',
    "批次说明" varchar(2000),
    "创建人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_获奖申报批次_名称" UNIQUE ("计划年度","批次名称"),
    CONSTRAINT "ck_获奖申报批次_年度" CHECK ("计划年度" BETWEEN 1900 AND 2200),
    CONSTRAINT "ck_获奖申报批次_申报日期" CHECK ("申报截止日期" >= "申报开始日期"),
    CONSTRAINT "ck_获奖申报批次_评审日期" CHECK ("评审截止日期" IS NULL OR "评审开始日期" IS NULL OR "评审截止日期" >= "评审开始日期"),
    CONSTRAINT "ck_获奖申报批次_限额" CHECK ("申报限额" IS NULL OR "申报限额" > 0),
    CONSTRAINT "ck_获奖申报批次_状态" CHECK ("状态" IN ('草稿','发布','关闭'))
);
CREATE INDEX IF NOT EXISTS "ix_获奖申报批次_状态日期" ON "获奖申报批次" ("状态","申报开始日期","申报截止日期");

CREATE TABLE IF NOT EXISTS "获奖申报" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "批次编号" bigint NOT NULL REFERENCES "获奖申报批次"("编号"),
    "申报名称" varchar(500) NOT NULL,
    "申报人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "获奖类别" varchar(100),
    "拟申报级别" varchar(100),
    "成果摘要" text,
    "关联成果类型" integer,
    "关联成果编号" integer,
    "关联项目编号" integer,
    "申报材料路径" text,
    "状态" varchar(12) NOT NULL DEFAULT '草稿',
    "提交时间" timestamp without time zone,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_获奖申报_状态" CHECK ("状态" IN ('草稿','已提交','评审中','拟推荐','已认定','未通过','已撤回')),
    CONSTRAINT "ck_获奖申报_关联类型" CHECK ("关联成果类型" IS NULL OR "关联成果类型" BETWEEN 1 AND 4)
);
CREATE INDEX IF NOT EXISTS "ix_获奖申报_批次状态" ON "获奖申报" ("批次编号","状态","更新时间" DESC);
CREATE INDEX IF NOT EXISTS "ix_获奖申报_申报人" ON "获奖申报" ("申报人编号","更新时间" DESC);

CREATE TABLE IF NOT EXISTS "获奖申报评审" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "申报编号" bigint NOT NULL REFERENCES "获奖申报"("编号") ON DELETE CASCADE,
    "评审专家编号" integer NOT NULL REFERENCES "人员"("编号"),
    "是否回避" boolean NOT NULL DEFAULT FALSE,
    "回避原因" varchar(1000),
    "评分" numeric(5,2),
    "评审意见" varchar(4000),
    "推荐结果" varchar(12),
    "提交时间" timestamp without time zone,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_获奖申报评审_专家" UNIQUE ("申报编号","评审专家编号"),
    CONSTRAINT "ck_获奖申报评审_评分" CHECK ("评分" IS NULL OR ("评分" >= 0 AND "评分" <= 100)),
    CONSTRAINT "ck_获奖申报评审_推荐" CHECK ("推荐结果" IS NULL OR "推荐结果" IN ('推荐','不推荐','待定'))
);

CREATE TABLE IF NOT EXISTS "获奖认定" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "申报编号" bigint NOT NULL REFERENCES "获奖申报"("编号"),
    "认定结果" varchar(12) NOT NULL DEFAULT '待认定',
    "成果获奖编号" integer REFERENCES "成果获奖"("编号"),
    "获奖名称" varchar(500),
    "获奖级别" varchar(100),
    "颁奖单位" varchar(300),
    "证书编号" varchar(200),
    "获奖日期" date,
    "认定意见" varchar(2000),
    "认定人编号" integer REFERENCES "人员"("编号"),
    "认定时间" timestamp without time zone,
    "证书路径" text,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_获奖认定_申报" UNIQUE ("申报编号"),
    CONSTRAINT "ck_获奖认定_结果" CHECK ("认定结果" IN ('待认定','已认定','不通过'))
);

INSERT INTO "权限" ("编号","上级编号","名称","路径","类型","备注")
VALUES (208,2,'成果与知识产权','科研办公/科研办公/成果与知识产权.html',TRUE,'扩展成果类型、知识产权生命周期和获奖申报评审')
ON CONFLICT ("编号") DO UPDATE SET "上级编号"=EXCLUDED."上级编号","名称"=EXCLUDED."名称","路径"=EXCLUDED."路径","类型"=EXCLUDED."类型","备注"=EXCLUDED."备注";
INSERT INTO "角色权限" ("角色编号","权限编号")
SELECT r."编号",208 FROM "角色" r
WHERE r."名称" IN ('系统管理员','科研管理员','科研秘书','科技办')
  AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=208);

UPDATE "系统迁移版本"
   SET "版本"=97,"脚本"='097_achievement_ip_award_extensions.sql',
       "检查摘要"='增加成果类型扩展、知识产权生命周期/缴费提醒和获奖申报批次评审认定',"应用时间"=CURRENT_TIMESTAMP
 WHERE "编号"=1;

COMMIT;
